function field(string $name,string $label,mixed $v='',string $type='text',bool $required=true,int $max=250): void { ?><label><?=e($label)?><input name="<?=e($name)?>" type="<?=e($type)?>" value="<?=e($v)?>" maxlength="<?=$max?>" <?=$required?'required':''?>></label><?php }
function textarea(string $name,string $label,mixed $v='',int $max=10000,bool $required=false): void { ?><label><?=e($label)?><textarea name="<?=e($name)?>" maxlength="<?=$max?>" <?=$required?'required':''?> rows="5"><?=e($v)?></textarea></label><?php }
function select_field(string $name,string $label,array $options,string $selected): void { ?><label><?=e($label)?><select name="<?=e($name)?>"><?php foreach($options as $v=>$text): ?><option value="<?=e($v)?>" <?=$selected===(string)$v?'selected':''?>><?=e($text)?></option><?php endforeach ?></select></label><?php }
function form_error(?string $error): void { if($error): ?><div class="error" role="alert"><?=e($error)?></div><?php endif; }
function order_statuses(): array { return array_intersect_key(labels(),array_flip(['new','confirmed','awaiting_payment','paid','shipped','cancelled'])); }
